SELECT r.project_id FROM user_project_relation r
JOIN project_info p ON p.id = r.project_id
WHERE r.user_id = #{userId} AND p.tenant_id = #{tenantId}

SELECT COUNT(*) FROM user_project_relation r
JOIN project_info p ON p.id = r.project_id
WHERE r.user_id = #{userId} AND r.project_id = #{projectId} AND p.tenant_id = #{tenantId}
